-- RCF-045: solo fixtures ficticios del bootstrap de applications.sql.
insert into public.application_methods(id,code,name,application_route) values
('71000000-0000-4000-8000-000000000099','R99','Sistema de riego ficticio','irrigation'),
('71000000-0000-4000-8000-000000000098','R98','Otro sistema ficticio','irrigation');
select public.create_application_order(pg_temp.order_data(),pg_temp.stages(),pg_temp.mixture());
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000002')||'{"method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":null,"application_route":"foliar"}',pg_temp.stages(),pg_temp.mixture());
select pg_temp.assert_true((select bool_and(application_number=1) from public.application_targets),'Foliar 1 y Riego 1 coexisten por etapa');
select pg_temp.assert_true((select application_route='irrigation' and water_l_ha is null from public.application_orders where id='90000000-0000-4000-8000-000000000002'),'vía deriva del medio, no del cliente; agua ausente no es cero');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000003'),pg_temp.stages(),pg_temp.mixture());
select pg_temp.assert_true((select bool_and(application_number=2 and application_route='foliar') from public.application_targets where order_id='90000000-0000-4000-8000-000000000003'),'serie foliar continúa independientemente');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":null,"application_number":1}',pg_temp.stages(),pg_temp.mixture())$q$,'ya está registrada','número repetido en misma vía rechazado');
select public.cancel_application_targets('90000000-0000-4000-8000-000000000002',pg_temp.target_ids('90000000-0000-4000-8000-000000000002'),'Cancelación ficticia');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000004')||'{"method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":null}',pg_temp.stages(),pg_temp.mixture());
select pg_temp.assert_true((select bool_and(application_number=2 and application_route='irrigation') from public.application_targets where order_id='90000000-0000-4000-8000-000000000004'),'cancelación de riego no libera número');
select pg_temp.expect_error($q$update public.application_methods set application_route='foliar' where id='71000000-0000-4000-8000-000000000099'$q$,'vía.*histórica','medio utilizado conserva vía histórica');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000005')||'{"water_l_ha":null}',pg_temp.stages(),pg_temp.mixture())$q$,'agua','foliar sin agua rechazado');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000005')||'{"method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":0}',pg_temp.stages(),pg_temp.mixture())$q$,'agua|mayor','riego con cero rechazado');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000005')||'{"method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":null,"recipe_source":{"order_id":"90000000-0000-4000-8000-000000000001","revision":0,"stage_id":"80000000-0000-4000-8000-000000000001"}}',pg_temp.stages(),pg_temp.mixture())$q$,'misma vía','receta base de otra vía rechazada');
select pg_temp.expect_error($q$select public.revise_application_order(jsonb_build_object('id','a0000000-0000-4000-8000-000000000099','order_id','90000000-0000-4000-8000-000000000004','expected_revision',0,'target_ids',pg_temp.target_ids('90000000-0000-4000-8000-000000000004'),'method_id','71000000-0000-4000-8000-000000000001','indicated_date','2026-01-03','scheduled_date','2026-01-07','water_l_ha',100,'observations','','reason','Cambio de vía ficticio'),pg_temp.mixture())$q$,'vía no se puede cambiar','receta guardada no cambia de vía');
select public.revise_application_order(jsonb_build_object('id','a0000000-0000-4000-8000-000000000098','order_id','90000000-0000-4000-8000-000000000004','expected_revision',0,'target_ids',pg_temp.target_ids('90000000-0000-4000-8000-000000000004'),'method_id','71000000-0000-4000-8000-000000000098','indicated_date','2026-01-03','scheduled_date','2026-01-07','water_l_ha',null,'observations','','reason','Otro medio de riego ficticio'),pg_temp.mixture());
select pg_temp.assert_true((select bool_and(after->'water_l_ha'='null'::jsonb) from public.application_changes),'revisión de riego conserva ausencia de agua');
select pg_temp.expect_error($q$update public.application_methods set application_route='foliar' where id='71000000-0000-4000-8000-000000000098'$q$,'vía.*histórica','medio utilizado en revisión también conserva vía');
select public.perform_application_targets('90000000-0000-4000-8000-000000000004',pg_temp.target_ids('90000000-0000-4000-8000-000000000004'),'{"actual_date":"2026-01-07","changed":false,"expected_revision":1}');
select pg_temp.assert_true((select bool_and(status='performed' and actual_water_l_ha is null) from public.application_targets where order_id='90000000-0000-4000-8000-000000000004'),'realización copia riego sin agua y conserva estado');
select public.correct_application_target(jsonb_build_object('id','b0000000-0000-4000-8000-000000000099','target_id',(pg_temp.target_ids('90000000-0000-4000-8000-000000000004'))[1],'expected_version',0,'actual_date','2026-01-08','water_l_ha',null,'equipment','Equipo ficticio','applicator','','observations','','reason','Corregir realización ficticia'),pg_temp.mixture());
select pg_temp.assert_true((select after->'water_l_ha'='null'::jsonb and before->'water_l_ha'='null'::jsonb from public.application_changes where kind='performance'),'corrección conserva null en ambas versiones históricas');
select public.create_application_order(pg_temp.order_data('90000000-0000-4000-8000-000000000005')||'{"field_id":"30000000-0000-4000-8000-000000000002","method_id":"71000000-0000-4000-8000-000000000099","water_l_ha":null}',array['80000000-0000-4000-8000-000000000003']::uuid[],pg_temp.mixture());
select pg_temp.assert_true((select application_number=1 from public.application_targets where order_id='90000000-0000-4000-8000-000000000005'),'otra etapa comienza riego desde uno');
select pg_temp.assert_true((select bool_and(application_route='foliar') from public.application_orders where id in('90000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000003')),'historia foliar no se reclasifica por otras recetas');
rollback;
